1	// ============================================================================
2	// ERP 下拉探针 —— 诊断「筛选模板 / 渠道」弹层为何读到空选项。
3	// 用法：
4	//   1) 在真实浏览器打开 ERP 订单页（待处理视图）：
5	//      https://www.sellfox.com/amzup-web-main/web/orderShip/index.html
6	//   2) F12 打开控制台，在控制台顶部的【frame 上下文下拉】里
7	//      选中承载订单表的那个 frame（通常是 orderShip/index.html，不是 top）。
8	//      —— 选错 frame 会找不到表格，探针会提示。
9	//   3) 把本文件全部内容粘贴进控制台回车，等它跑完（约 8 秒），
10	//      把打印出来的整段 [PROBE] 日志复制发回。
11	// 本探针【只点击、不下单、不发货】，安全。
12	// ============================================================================
13	(async () => {
14	  const P = (...a) => console.log("[PROBE]", ...a);
15	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
16	  const norm = (s) => (s || "").replace(/　/g, " ").replace(/\s/g, "");
17	  const qsa = (sel) => [...document.querySelectorAll(sel)];
18	  const isVisible = (el) => {
19	    if (!el) return false;
20	    const st = getComputedStyle(el);
21	    if (st.display === "none" || st.visibility === "hidden" || st.opacity === "0") return false;
22	    if (el.offsetParent === null && st.position !== "fixed") return false;
23	    return true;
24	  };
25	  const realClick = (el) => {
26	    try { el.scrollIntoView({ block: "center" }); } catch (e) {}
27	    const r = el.getBoundingClientRect();
28	    const base = { bubbles: true, cancelable: true, view: window,
29	      clientX: r.left + r.width / 2, clientY: r.top + r.height / 2, button: 0, buttons: 1 };
30	    for (const t of ["pointerover", "pointerenter", "pointerdown", "mousedown", "pointerup", "mouseup", "click"]) {
31	      let ev;
32	      try { ev = t.startsWith("pointer") ? new PointerEvent(t, { ...base, pointerId: 1, isPrimary: true }) : new MouseEvent(t, base); }
33	      catch (e) { ev = new MouseEvent(t.replace("pointer", "mouse"), base); }
34	      el.dispatchEvent(ev);
35	    }
36	  };
37	  const short = (s, n = 60) => { s = (s || "").replace(/\s+/g, " ").trim(); return s.length > n ? s.slice(0, n) + "…" : s; };
38	  const desc = (el) => {
39	    if (!el) return "null";
40	    const cls = (el.getAttribute("class") || "").slice(0, 60);
41	    return `<${el.tagName.toLowerCase()} class="${cls}"> "${short(el.innerText, 40)}"`;
42	  };
43	
44	  // ---- frame 自检 ----
45	  P("URL =", location.href);
46	  const hasTable = !!document.querySelector(".vxe-table, .vxe-header--column");
47	  P("本 frame 是否含 vxe 订单表 =", hasTable);
48	  if (!hasTable) {
49	    P("⚠️ 当前 frame 没有订单表！请在控制台顶部 frame 下拉里改选 orderShip/index.html 那个 frame，再重跑本探针。");
50	    // 不 return，继续探测下拉，或许仍有信息
51	  }
52	
53	  // ============ 1) 筛选模板 ============
54	  P("========== [1] 筛选模板 ==========");
55	  const tplTriggers = qsa("button, .el-button, span, div, li, a, [class*=btn]")
56	    .filter((e) => norm(e.innerText) === norm("筛选模板") && isVisible(e));
57	  P(`文本恰为「筛选模板」的可见元素 = ${tplTriggers.length} 个：`);
58	  tplTriggers.forEach((e, i) => P(`   #${i} ${desc(e)}  y=${Math.round(e.getBoundingClientRect().top)}`));
59	  if (tplTriggers.length) {
60	    // 取 y 最靠上的（与扩展 findByExactText 一致）
61	    const trig = tplTriggers.slice().sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top)[0];
62	    P("点击 #0（y 最靠上）:", desc(trig));
63	    const before = new Set(qsa(".el-popper, .el-popover, .el-dropdown-menu, .el-select-dropdown"));
64	    realClick(trig);
65	    await sleep(1500);
66	    const poppers = qsa(".el-popper, .el-popover, .el-dropdown-menu, .el-select-dropdown");
67	    const newVisible = poppers.filter((p) => isVisible(p));
68	    P(`点击后 可见弹层(.el-popper/.el-popover/.el-dropdown-menu/.el-select-dropdown) = ${newVisible.length} 个，其中新增 ${poppers.filter((p) => !before.has(p)).length} 个`);
69	    newVisible.forEach((p, i) => P(`   弹层#${i} ${desc(p)}`));
70	    // 弹层里有没有「未取消等待发货」
71	    const hit = qsa("span, div, li, a").filter((e) => isVisible(e) && norm(e.innerText) === norm("未取消等待发货"));
72	    P(`文本恰为「未取消等待发货」的可见元素 = ${hit.length} 个`);
73	    hit.forEach((e, i) => P(`   命中#${i} ${desc(e)}`));
74	    // 弹层里所有短文本候选（帮助看真实模板名/结构）
75	    if (newVisible.length) {
76	      const leaves = qsa("span, li, a, div, td, p").filter((e) =>
77	        isVisible(e) && e.children.length === 0 && norm(e.innerText).length > 0 && norm(e.innerText).length < 20 &&
78	        newVisible.some((p) => p.contains(e)));
79	      P("弹层内叶子短文本（去重前 40 个）:", [...new Set(leaves.map((e) => (e.innerText || "").trim()))].slice(0, 40));
80	    }
81	    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
82	    await sleep(500);
83	  } else {
84	    P("⚠️ 没有任何可见元素文本恰为「筛选模板」。列出含「筛选/模板」字样的可见元素以便定位真实触发点：");
85	    qsa("button, .el-button, span, div, li, a, [class*=btn]")
86	      .filter((e) => isVisible(e) && /筛选|模板/.test(e.innerText || "") && e.children.length <= 2)
87	      .slice(0, 15).forEach((e, i) => P(`   #${i} ${desc(e)}`));
88	  }
89	
90	  // ============ 2) 渠道 ============
91	  P("========== [2] 渠道 ==========");
92	  const chanInputs = qsa("input[placeholder*='渠道']");
93	  P(`input[placeholder*='渠道'] = ${chanInputs.length} 个：`);
94	  chanInputs.forEach((e, i) => P(`   #${i} placeholder="${e.placeholder}" visible=${isVisible(e)}`));
95	  const chanTrig = chanInputs.find((e) => isVisible(e)) || chanInputs[0];
96	  if (chanTrig) {
97	    P("点击渠道输入框:", `placeholder="${chanTrig.placeholder}"`);
98	    realClick(chanTrig);
99	    await sleep(1500);
100	    const labels = qsa("span.main_label");
101	    const visLabels = labels.filter((e) => isVisible(e));
102	    P(`span.main_label 总数 = ${labels.length}，其中可见 = ${visLabels.length}`);
103	    P("可见 span.main_label 文本:", [...new Set(visLabels.map((e) => (e.innerText || "").trim()).filter(Boolean))].sort());
104	    if (labels.length && !visLabels.length) {
105	      P("⚠️ main_label 存在但全不可见 → 弹层可能没真正展开。示例元素:", desc(labels[0]));
106	    }
107	    // 弹层容器
108	    const dds = qsa(".el-popper, .el-select-dropdown, .el-popover, .el-cascader__dropdown").filter((p) => isVisible(p));
109	    P(`点击后可见下拉容器 = ${dds.length} 个`);
110	    dds.forEach((p, i) => P(`   容器#${i} ${desc(p)}`));
111	    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
112	  } else {
113	    P("⚠️ 没有 input[placeholder*='渠道']。列出所有可见 input 的 placeholder 以便定位：");
114	    qsa("input").filter(isVisible).slice(0, 20).forEach((e, i) => P(`   #${i} placeholder="${e.placeholder}"`));
115	    P("另列出含「渠道」字样的可见元素:");
116	    qsa("span, div, label, button").filter((e) => isVisible(e) && /渠道/.test(e.innerText || "") && e.children.length <= 2)
117	      .slice(0, 15).forEach((e, i) => P(`   #${i} ${desc(e)}`));
118	  }
119	  P("========== 探针结束，请把以上全部 [PROBE] 行复制发回 ==========");
120	})();
