1	// lib.js —— 注入到 ERP / WMS 页面的共享 DOM 工具。
2	// 通过 chrome.scripting.executeScript({files:[...]}) 注入，每次调用都会重跑，故用幂等守卫避免重复定义。
3	window.__HWC = window.__HWC || (function () {
4	  const H = {};
5	
6	  H.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
7	
8	  // 去掉全部空白（含全角空格）再比较文本——ERP/WMS 按钮文字常夹空格（如「关 闭」「物流下单」）。
9	  H.norm = (s) => (s || "").replace(/　/g, " ").replace(/\s/g, "");
10	
11	  H.qsa = (sel, root) => [...(root || document).querySelectorAll(sel)];
12	
13	  // 是否真正可见（排除 display:none / 隐藏弹窗）。用于替代 Playwright 的 :visible。
14	  H.isVisible = (el) => {
15	    if (!el) return false;
16	    if (el.offsetParent === null && getComputedStyle(el).position !== "fixed") return false;
17	    const st = getComputedStyle(el);
18	    return st.display !== "none" && st.visibility !== "hidden" && st.opacity !== "0";
19	  };
20	
21	  // 【核心】完整鼠标事件序列的合成点击。排雷 spike 已证明：只有派发
22	  // pointerover→pointerdown→mousedown→pointerup→mouseup→click 完整序列，才能驱动
23	  // vxe-table / Element-UI 的复选框、下拉、按钮（el.click() 只发 click 常被框架忽略=静默失败）。
24	  H.realClick = (el) => {
25	    if (!el) return false;
26	    try { el.scrollIntoView({ block: "center" }); } catch (e) {}
27	    const r = el.getBoundingClientRect();
28	    const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
29	    const base = { bubbles: true, cancelable: true, view: window, clientX: cx, clientY: cy, button: 0, buttons: 1 };
30	    for (const type of ["pointerover", "pointerenter", "pointerdown", "mousedown", "pointerup", "mouseup", "click"]) {
31	      let ev;
32	      try {
33	        ev = type.startsWith("pointer")
34	          ? new PointerEvent(type, { ...base, pointerId: 1, isPrimary: true })
35	          : new MouseEvent(type, base);
36	      } catch (e) {
37	        ev = new MouseEvent(type.replace("pointer", "mouse"), base);
38	      }
39	      el.dispatchEvent(ev);
40	    }
41	    return true;
42	  };
43	
44	  // 轮询等待 fn() 返回真值；超时返回 null。（页面上下文可用 Date.now）
45	  H.waitFor = async (fn, { timeout = 12000, interval = 300 } = {}) => {
46	    const end = Date.now() + timeout;
47	    while (Date.now() < end) {
48	      try { const v = fn(); if (v) return v; } catch (e) {}
49	      await H.sleep(interval);
50	    }
51	    return null;
52	  };
53	
54	  // 在候选选择器里找“去空白后文本 == text、可见、可选排除表格行内”的元素，返回 y 最靠上的一个。
55	  H.findByExactText = (text, { selectors = "button, .el-button, span, div, li, a, [class*=btn]", excludeRowSel = null } = {}) => {
56	    let best = null, minY = Infinity;
57	    for (const el of H.qsa(selectors)) {
58	      if (H.norm(el.innerText) !== H.norm(text)) continue;
59	      if (excludeRowSel && el.closest(excludeRowSel)) continue;
60	      if (!H.isVisible(el)) continue;
61	      const y = el.getBoundingClientRect().top;
62	      if (y < minY) { minY = y; best = el; }
63	    }
64	    return best;
65	  };
66	
67	  return H;
68	})();
