1	// content_erp.js —— ERP（赛狐 Sellfox）页面内操作，照搬 automation/erp.py。
2	// 由 background 注入到 sellfox.com 的所有 frame；只有承载订单表(vxe)的那个 frame 会真正干活，
3	// 其余 frame 的 dispatch 返回 null，被 background 过滤掉。
4	// 每个 op 把过程日志 push 进 L，随结果一起返回，由 background 转发到 popup 实时显示。
5	window.__HWC_ERP = window.__HWC_ERP || (function () {
6	  const H = window.__HWC;
7	  const FILTER_TEMPLATE = "未取消等待发货";
8	
9	  // 该 frame 是否承载订单业务视图？（有 vxe 表格 或 待处理/物流下单 相关 DOM）
10	  function isErpFrame() {
11	    return !!(document.querySelector(".vxe-table, .vxe-header--column") ||
12	              H.findByExactText("物流下单") ||
13	              H.qsa("*").some((e) => e.children.length === 0 && H.norm(e.innerText) === "待处理"));
14	  }
15	
16	  function dismissNotifications() {
17	    try { H.qsa(".el-notification").forEach((e) => e.remove()); } catch (e) {}
18	  }
19	
20	  async function dismissAlertModal(L) {
21	    for (let i = 0; i < 3; i++) {
22	      let closed = false;
23	      for (const t of ["稍后处理", "关闭", "我知道了", "取消"]) {
24	        const b = H.qsa(".el-dialog button, .el-message-box button")
25	          .find((x) => H.isVisible(x) && H.norm(x.innerText) === H.norm(t));
26	        if (b) { H.realClick(b); closed = true; await H.sleep(800); break; }
27	      }
28	      if (!closed) break;
29	    }
30	  }
31	
32	  async function gotoView(name, L) {
33	    const el = H.findByExactText(name);
34	    if (!el) { L.push(`[ERP] 未找到视图入口：${name}`); return false; }
35	    H.realClick(el);
36	    await H.sleep(3000);
37	    L.push(`[ERP] 切换到视图：${name}`);
38	    return true;
39	  }
40	
41	  // 需求1：选筛选模板（排除取消/退款/换货/禁处理单）。⚠️实测选模板会重置渠道筛选，
42	  // 故调用方必须【先选模板，再筛渠道】，让渠道筛选最后生效（安全底线）。
43	  async function selectFilterTemplate(name, L) {
44	    if (!name) return true;
45	    dismissNotifications();
46	    const trigger = H.findByExactText("筛选模板");
47	    if (!trigger) { L.push("[ERP] 未找到『筛选模板』触发控件"); return false; }
48	    H.realClick(trigger);
49	    await H.sleep(1200);
50	    // 弹层里精确匹配模板名（精确匹配，避免误点『单品单件未取消待发货』）
51	    const opt = H.qsa(".el-popper, .el-popover, .el-dropdown-menu, span, div, li, a")
52	      .find((e) => H.isVisible(e) && H.norm(e.innerText) === H.norm(name));
53	    if (!opt) {
54	      L.push(`[ERP] 未找到筛选模板选项：${name}`);
55	      // 关键：找不到也要按 Esc 关掉筛选模板弹层，否则它是 single_el_popover 单例弹层，
56	      // 残留开着会导致下一步点渠道 input 只关旧弹层、不弹渠道下拉（实测渠道选项为空）。
57	      try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
58	      await H.sleep(400);
59	      return false;
60	    }
61	    H.realClick(opt);
62	    await H.sleep(2000);
63	    L.push(`[ERP] 已选择筛选模板：${name}`);
64	    return true;
65	  }
66	
67	  // 渠道筛选。触发 input[placeholder*='渠道'] -> 弹层 span.main_label 精确匹配 -> 确定。
68	  // 返回 {ok, available}。available = 找不到时下拉里实际可选渠道（便于判断是漏筛还是本就没单）。
69	  async function filterByChannel(channel, L) {
70	    if (!channel) return { ok: true };
71	    dismissNotifications();
72	    // 先按 Esc 清掉可能残留的弹层（如上一步筛选模板未关的 popover）。渠道弹层是 single_el_popover
73	    // 单例机制：若有旧弹层开着，点渠道 input 只会关旧弹层、不弹渠道下拉 → 选项为空（实测）。
74	    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
75	    await H.sleep(400);
76	    const trigger = document.querySelector("input[placeholder*='渠道']");
77	    if (!trigger) { L.push("[ERP] 未找到渠道筛选输入框"); return { ok: false, available: [] }; }
78	    H.realClick(trigger);
79	    await H.sleep(1200);
80	    // span.main_label 精确匹配（别用包含——订单行物流信息列也含渠道文字会误点）
81	    let picked = null;
82	    for (const el of H.qsa("span.main_label")) {
83	      if (H.isVisible(el) && (el.innerText || "").trim() === channel) { picked = el; break; }
84	    }
85	    if (!picked) {
86	      const available = [...new Set(H.qsa("span.main_label")
87	        .filter((e) => H.isVisible(e)).map((e) => (e.innerText || "").trim()).filter(Boolean))].sort();
88	      L.push(`[ERP] 未找到渠道选项：${channel}；当前下拉可选渠道=${JSON.stringify(available)}`);
89	      try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
90	      return { ok: false, available };
91	    }
92	    H.realClick(picked);
93	    L.push(`[ERP] 渠道选中：${channel}`);
94	    await H.sleep(500);
95	    // 确定（限可见弹层）
96	    const okBtn = H.qsa(".el-popper button, button").find((b) =>
97	      H.isVisible(b) && ["确定", "确认"].includes(H.norm(b.innerText)));
98	    if (okBtn) H.realClick(okBtn);
99	    await H.sleep(2500);
100	    return { ok: true };
101	  }
102	
103	  // 订单总数：.total_style 取最大（异步加载，轮询到 >0 或超时）。兜底 .parentRowGroup 计数。
104	  async function countOrders(L) {
105	    const read = () => {
106	      const a = H.qsa(".total_style")
107	        .map((e) => parseInt((e.innerText || "0").replace(/\D/g, ""), 10)).filter((x) => !isNaN(x));
108	      return a.length ? Math.max(...a) : 0;
109	    };
110	    for (let i = 0; i < 5; i++) {
111	      const n = read();
112	      if (n > 0) return n;
113	      await H.sleep(1000);
114	    }
115	    return H.qsa(".parentRowGroup").length;
116	  }
117	
118	  // vxe 表头全选 + 校验确有行被勾选。
119	  async function selectAll(L) {
120	    const th = document.querySelector(".vxe-header--column.col--checkbox .vxe-cell--checkbox");
121	    if (!th) { L.push("[ERP] 未找到 vxe 表头全选框"); return false; }
122	    if ((th.getAttribute("class") || "").includes("is--disabled")) {
123	      L.push("[ERP] 表头全选框禁用（可能无数据）"); return false;
124	    }
125	    H.realClick(th);
126	    await H.sleep(1500);
127	    const checked = H.qsa(".vxe-body--row.row--checked, .vxe-cell--checkbox.is--checked").length;
128	    if (!checked) { L.push("[ERP] 全选后未检测到勾选行"); return false; }
129	    L.push(`[ERP] 已全选，勾选标记数≈${checked}`);
130	    return true;
131	  }
132	
133	  // 工具栏「物流下单」按钮（排除行内同名按钮，取 y 最靠上的可见按钮）。
134	  function findToolbarButton(text) {
135	    return H.findByExactText(text, {
136	      selectors: "button, .el-button, .base_button_comp, .myj-btn, [class*=btn]",
137	      excludeRowSel: ".vxe-body--row",
138	    });
139	  }
140	
141	  function parseResultText(txt) {
142	    if (!txt) return { success: null, fail: null, fail_orders: [], text: "" };
143	    const ms = txt.match(/成功[:：]?\s*(\d+)/);
144	    const mf = txt.match(/失败[:：]?\s*(\d+)/);
145	    const orders = [...new Set((txt.match(/\bP[0-9A-Z]{9,15}\b/g) || []))];
146	    return { success: ms ? +ms[1] : null, fail: mf ? +mf[1] : null, fail_orders: orders, text: txt };
147	  }
148	
149	  async function readResultDialog(L) {
150	    let txt = null;
151	    await H.waitFor(() => {
152	      const dlg = H.qsa(".el-dialog__wrapper .el-dialog, .el-message-box")
153	        .find((d) => H.isVisible(d));
154	      if (dlg) { txt = (dlg.innerText || "").trim(); return true; }
155	      return false;
156	    }, { timeout: 30000, interval: 1000 });
157	    if (txt) L.push("[ERP] 物流下单结果:\n" + txt.slice(0, 800));
158	    // 关闭：只点可见弹窗内的关闭/确定按钮
159	    const btn = H.qsa(".el-dialog__wrapper button, .el-message-box__wrapper button").find((b) =>
160	      H.isVisible(b) && ["关闭", "确定", "知道了", "ok", "OK"].includes(H.norm(b.innerText)));
161	    if (btn) H.realClick(btn);
162	    else try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
163	    await H.sleep(1000);
164	    return parseResultText(txt);
165	  }
166	
167	  // ===== 主 op：物流下单 =====
168	  async function placeOrder({ channel, dry }) {
169	    const L = [];
170	    await dismissAlertModal(L);
171	    dismissNotifications();
172	    if (!(await gotoView("待处理", L))) return { logs: L, error: "无法进入待处理视图" };
173	
174	    // 先选模板 -> 再筛渠道（顺序不可反：模板会重置渠道筛选，让渠道最后生效=安全底线）
175	    if (!(await selectFilterTemplate(FILTER_TEMPLATE, L)))
176	      L.push("[ERP] ⚠️ 筛选模板未选中，继续（渠道筛选仍保证范围，仅少了取消/退款单排除）");
177	
178	    if (channel) {
179	      const f = await filterByChannel(channel, L);
180	      if (!f.ok) {
181	        L.push(`[ERP] 渠道筛选未成功(${channel})，为避免全量误下单，跳过本渠道`);
182	        return { logs: L, count: 0, channelFilterFailed: true, available: f.available || [] };
183	      }
184	    }
185	
186	    const n = await countOrders(L);
187	    L.push(`[ERP] 待处理订单 共 ${n} 条${channel ? `（渠道：${channel}）` : ""}`);
188	    if (n === 0) return { logs: L, count: 0, success: 0, fail: 0, fail_orders: [] };
189	
190	    if (!(await selectAll(L))) return { logs: L, count: n, error: "全选失败" };
191	
192	    if (dry) {
193	      L.push(`[ERP][DRY] 将点击【物流下单】处理 ${n} 条（已跳过实际点击）`);
194	      return { logs: L, count: n, dry: true };
195	    }
196	
197	    const btn = findToolbarButton("物流下单");
198	    if (!btn) return { logs: L, count: n, error: "未定位到工具栏物流下单按钮" };
199	    H.realClick(btn);
200	    L.push(`[ERP] 已点击工具栏【物流下单】，处理 ${n} 条`);
201	    await H.sleep(3000);
202	    const r = await readResultDialog(L);
203	    if (r.fail) L.push(`[ERP] ⚠️ 物流下单失败 ${r.fail} 单：${JSON.stringify(r.fail_orders)}`);
204	    return { logs: L, count: n, success: r.success, fail: r.fail, fail_orders: r.fail_orders, result_text: r.text };
205	  }
206	
207	  // ===== op：获取跟踪号（三方仓 > 待更新 > 手动更新）=====
208	  async function updateStatus() {
209	    const L = [];
210	    if (!(await gotoView("三方仓", L))) return { logs: L, error: "进三方仓失败" };
211	    if (!(await gotoView("待更新", L))) return { logs: L, error: "待更新子标签失败" };
212	    const n = await countOrders(L);
213	    if (!n) { L.push("[ERP] 待更新 0 条"); return { logs: L, total: 0, got: 0, fail: 0 }; }
214	    if (!(await selectAll(L))) return { logs: L, error: "待更新全选失败" };
215	    const btn = H.findByExactText("手动更新", {
216	      selectors: "button, .el-button, .base_button_comp, [class*=btn]", excludeRowSel: ".vxe-body--row" });
217	    if (!btn) return { logs: L, total: n, error: "无手动更新按钮" };
218	    H.realClick(btn);
219	    L.push(`[ERP] 已全选 ${n} 条并点【手动更新】，拉取跟踪号中…`);
220	    let final = null;
221	    await H.waitFor(() => {
222	      const d = H.qsa(".el-dialog, .el-message-box").find((e) => H.isVisible(e));
223	      if (d) { final = (d.innerText || "").trim(); if (final.includes("获取完成") || final.includes("100%")) return true; }
224	      return false;
225	    }, { timeout: 60000, interval: 1000 });
