1	// content_wms.js —— WMS（海外仓）页面内操作，照搬 automation/wms.py。
2	// 注入到 193.112.93.60:9999 的 frame。承载订单表的 frame 干活，其余返回 null。
3	window.__HWC_WMS = window.__HWC_WMS || (function () {
4	  const H = window.__HWC;
5	
6	  function isOrderFrame() {
7	    return !!(document.querySelector(".el-table") || H.findByExactText("批量发货"));
8	  }
9	
10	  // 读页面顶部「Hi，XXX」显示名（判断当前登录的是金猫/黑猫）。读不到返回 ''。
11	  function currentAccount() {
12	    let acc = "";
13	    for (const e of H.qsa("*")) {
14	      if (e.children.length || e.offsetParent === null) continue;
15	      const m = (e.innerText || "").trim().match(/Hi[，,]\s*(.+)$/);
16	      if (m) acc = m[1].trim();
17	    }
18	    return acc;
19	  }
20	
21	  // 未发货订单数：优先读 .el-pagination__total「共N条」（固定列使 .el-table__row 翻倍，别直接数）。
22	  function countRows() {
23	    const el = document.querySelector(".el-pagination__total");
24	    if (el) { const m = (el.innerText || "").match(/\d+/); if (m) return +m[0]; }
25	    const rows = H.qsa(".el-table__row");
26	    return rows.length ? Math.floor(rows.length / 2) : 0;
27	  }
28	
29	  async function closeTips(rounds = 4) {
30	    const texts = [];
31	    for (let i = 0; i < rounds; i++) {
32	      const box = H.qsa(".el-message-box__wrapper .el-message-box").find((b) => H.isVisible(b));
33	      if (!box) break;
34	      texts.push((box.innerText || "").trim().slice(0, 120));
35	      const btn = H.qsa(".el-message-box__wrapper button").find((b) =>
36	        H.isVisible(b) && ["ok", "OK", "确定", "确认", "关闭", "知道了"].includes(H.norm(b.innerText)));
37	      if (btn) H.realClick(btn);
38	      else try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
39	      await H.sleep(1000);
40	    }
41	    return texts;
42	  }
43	
44	  // 等加载遮罩 .loading-indicator-overlay 消失（改快递方后列表刷新的遮罩会拦截点击）。
45	  async function waitLoadingGone(L, timeout = 15000) {
46	    const gone = await H.waitFor(() => !H.qsa(".loading-indicator-overlay").some((el) => H.isVisible(el)),
47	      { timeout, interval: 300 });
48	    if (!gone) L.push("[WMS] ⚠️ 等待加载遮罩消失超时，继续尝试");
49	  }
50	
51	  async function ensureUnshipped(L) {
52	    const btn = H.findByExactText("查询");
53	    if (btn) { H.realClick(btn); await H.sleep(3000); }
54	    else L.push("[WMS] 未找到『查询』按钮");
55	  }
56	
57	  async function selectAll(L) {
58	    const cb = document.querySelector(".el-table__header-wrapper .el-checkbox, .el-table__header .el-checkbox");
59	    if (!cb) { L.push("[WMS] 未找到表头全选框"); return false; }
60	    if ((cb.getAttribute("class") || "").includes("is-disabled")) { L.push("[WMS] 全选框禁用（无数据）"); return false; }
61	    H.realClick(cb);
62	    await H.sleep(1000);
63	    return true;
64	  }
65	
66	  function closeDialog() {
67	    const b = H.qsa(".el-dialog button, .el-dialog .el-dialog__headerbtn").find((x) =>
68	      H.isVisible(x) && (["取消"].includes(H.norm(x.innerText)) || x.classList.contains("el-dialog__headerbtn")));
69	    if (b) H.realClick(b);
70	    else try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
71	  }
72	
73	  // 批量修改快递方 = courier。DRY 下不点确认。
74	  async function setCourier(courier, dry, L) {
75	    const open = H.findByExactText("批量修改快递方");
76	    if (!open) { L.push("[WMS] 未找到『批量修改快递方』按钮"); return false; }
77	    H.realClick(open);
78	    await H.sleep(1500);
79	    // 可见弹窗内的快递方下拉
80	    const sel = H.qsa(".el-dialog .el-select").find((s) => H.isVisible(s));
81	    if (!sel) { L.push("[WMS] 未找到可见的快递方下拉"); closeDialog(); return false; }
82	    H.realClick(sel);
83	    await H.sleep(1000);
84	    const opt = H.qsa(".el-select-dropdown__item").find((o) => H.isVisible(o) && (o.innerText || "").trim() === courier);
85	    if (!opt) { L.push(`[WMS] 未找到快递方选项 ${courier}`); closeDialog(); return false; }
86	    H.realClick(opt);
87	    await H.sleep(500);
88	    if (dry) { L.push(`[WMS][DRY] 将设置快递方 = ${courier}（跳过确认）`); closeDialog(); return true; }
89	    const ok = H.qsa(".el-dialog button.el-button--primary, .el-dialog button").find((b) =>
90	      H.isVisible(b) && (b.classList.contains("el-button--primary") || ["确认", "确定"].includes(H.norm(b.innerText))));
91	    if (!ok) { L.push("[WMS] 未找到快递方确认按钮"); return false; }
92	    H.realClick(ok);
93	    await H.sleep(2000);
94	    const tips = await closeTips();
95	    L.push(`[WMS] 已设置快递方 = ${courier}  Tip=${JSON.stringify(tips)}`);
96	    return true;
97	  }
98	
99	  // 需求2：改快递方后设「是否偏远地区」= 否 并查询（只发非偏远，偏远单留存）。
100	  async function setRemoteFilter(value, L) {
101	    await closeTips();
102	    await waitLoadingGone(L);
103	    const input = document.querySelector("input[placeholder*='偏远']");
104	    if (!input) { L.push("[WMS] 未找到「是否偏远地区」控件"); return false; }
105	    H.realClick(input);
106	    await H.sleep(1000);
107	    const opt = H.qsa(".el-select-dropdown__item").find((o) => H.isVisible(o) && (o.innerText || "").trim() === value);
108	    if (!opt) { L.push(`[WMS] 未找到「是否偏远地区」选项「${value}」`); return false; }
109	    H.realClick(opt);
110	    await H.sleep(500);
111	    await waitLoadingGone(L);
112	    const q = H.findByExactText("查询");
113	    if (q) { H.realClick(q); await H.sleep(3000); }
