1	// background.js —— 跨标签编排（service worker）。
2	// 守住核心业务规则：按渠道串行闭环、先选模板→再筛渠道、渠道→店铺/快递方映射、失败留存。
3	// WMS 同源单账号约束：同一浏览器 WMS 只能登一个店铺，故【只处理当前登录店铺对应的渠道】，
4	// 另一店铺的渠道跳过并提示切换后再跑一次（连 ERP 下单都不做，避免下了单发不掉变残留单）。
5	importScripts("rules.js");
6	
7	const ERP_URL = "https://www.sellfox.com/amzup-web-main/web/orderShip/index.html";
8	const ORDERINFO_WMS = "http://193.112.93.60:9999/orderInfo/page/orderInfo.html";
9	const INDEX_WMS = "http://193.112.93.60:9999/index.html";
10	
11	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
12	
13	// 日志缓冲放在后台，弹窗只是"观众"。弹窗关闭/重开不影响日志——重开时从这里重放。
14	// 也写一份到 storage.session（内存级，不落盘），防 service worker 被回收后丢失。
15	let logBuffer = [];
16	let running = false;
17	const ports = new Set();
18	
19	// MV3 保活：service worker 空闲 ~30s 就被回收，会杀死正在跑的任务（表现=日志卡在某行不动）。
20	// 运行期间每 20s 调一次 chrome API，重置空闲计时器，盖住 sleep/等待页面加载 的静默间隙。
21	let keepAliveTimer = null;
22	function startKeepAlive() {
23	  if (keepAliveTimer) return;
24	  keepAliveTimer = setInterval(() => { try { chrome.runtime.getPlatformInfo(() => {}); } catch (e) {} }, 20000);
25	}
26	function stopKeepAlive() { if (keepAliveTimer) { clearInterval(keepAliveTimer); keepAliveTimer = null; } }
27	
28	function broadcast(msg) { for (const p of ports) { try { p.postMessage(msg); } catch (e) {} } }
29	function log(line) {
30	  logBuffer.push(line);
31	  broadcast({ type: "log", line });
32	  try { chrome.storage.session.set({ hwcLog: logBuffer, hwcRunning: running }); } catch (e) {}
33	}
34	async function loadBufferIfEmpty() {
35	  if (logBuffer.length) return;
36	  try {
37	    const s = await chrome.storage.session.get(["hwcLog", "hwcRunning"]);
38	    if (s.hwcLog) logBuffer = s.hwcLog;
39	    running = !!s.hwcRunning;
40	  } catch (e) {}
41	}
42	
43	async function findTab(pattern) {
44	  const tabs = await chrome.tabs.query({ url: pattern });
45	  return tabs[0] || null;
46	}
47	
48	// 导航并【轮询等页面就绪】——不再赌"加载完成事件"（跳到相同 URL 时该事件可能不触发=假死）。
49	// 发起跳转后，每 1.5s 注入并调一次 opMsg，直到 okFn(结果) 为真（说明我们要的 DOM 已出现）。
50	// 页面重载中 executeScript 可能抛错，忽略后重试。超时返回最后一次结果。
51	async function gotoUntil(tabId, url, side, opMsg, okFn, timeout = 40000) {
52	  await chrome.tabs.update(tabId, { url });
53	  const deadline = Date.now() + timeout;
54	  let last = null;
55	  while (Date.now() < deadline) {
56	    await sleep(1500);
57	    try { const r = await runOp(tabId, side, opMsg); last = r; if (okFn(r)) return r; }
58	    catch (e) { last = { error: String((e && e.message) || e) }; }
59	  }
60	  return last;
61	}
62	
63	// 给 Promise 加超时，防止某个坏 frame（永远加载中的 iframe）让 executeScript 永不返回=假死。
64	function withTimeout(p, ms, label) {
65	  return Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error("超时:" + label)), ms))]);
66	}
67	
68	async function getFrames(tabId) {
69	  try {
70	    const fs = await chrome.webNavigation.getAllFrames({ tabId });
71	    return fs && fs.length ? fs : [{ frameId: 0, url: "" }];
72	  } catch (e) { return [{ frameId: 0, url: "" }]; }
73	}
74	
75	// 【关键】逐个 frame 注入并 dispatch，每个 frame 单独限时。
76	// 不再用 allFrames:true 一次性注入——那样只要有一个坏 frame 就整体卡死（sellfox 有常驻加载的 iframe）。
77	async function runOp(tabId, side, opMsg) {
78	  const files = side === "erp" ? ["lib.js", "content_erp.js"] : ["lib.js", "content_wms.js"];
79	  const glob = side === "erp" ? "__HWC_ERP" : "__HWC_WMS";
80	  const frames = await getFrames(tabId);
81	  for (const fr of frames) {
82	    try {
83	      await withTimeout(
84	        chrome.scripting.executeScript({ target: { tabId, frameIds: [fr.frameId] }, files }),
85	        6000, "注入");
86	      const res = await withTimeout(
87	        chrome.scripting.executeScript({
88	          target: { tabId, frameIds: [fr.frameId] },
89	          func: async (g, m) => {
90	            try { const o = window[g]; return o ? await o.dispatch(m) : null; }
91	            catch (e) { return { error: String((e && e.stack) || e) }; }
92	          },
93	          args: [glob, opMsg],
94	        }),
95	        90000, "执行");
96	      const r = res && res[0] && res[0].result;
97	      if (r !== null && r !== undefined) return r;   // 命中承载目标 DOM 的 frame
98	    } catch (e) { /* 该 frame 无权限/已卸载/超时，跳过 */ }
99	  }
100	  return null;
101	}
102	
103	// 在页面里跑的自包含探测函数（不依赖 lib.js）：报告关键控件结构 + 当前【已打开】的下拉选项。
104	function erpProbeInPage() {
105	  const norm = (s) => (s || "").replace(/\s/g, "");
106	  const vis = (el) => !!el && el.offsetParent !== null;
107	  const q = (sel) => { try { return document.querySelectorAll(sel).length; } catch (e) { return -1; } };
108	
109	  const wuliu = [...document.querySelectorAll("button,.el-button,[class*=btn],span,div,a")]
110	    .filter((e) => norm(e.innerText) === "物流下单").length;
111	  const tplEls = [...document.querySelectorAll("*")].filter((e) => !e.children.length && norm(e.innerText) === "筛选模板");
112	
113	  const counts = {
114	    url: location.href.slice(0, 55),
115	    vxe表: q(".vxe-table,.vxe-header--column"),
116	    vxe全选框: q(".vxe-header--column.col--checkbox .vxe-cell--checkbox"),
117	    物流下单按钮: wuliu,
118	    筛选模板: tplEls.length,
119	    渠道输入框: q("input[placeholder*='渠道']"),
120	    total_style: q(".total_style"),
121	    渠道main_label: q("span.main_label"),
122	  };
123	  if (counts.vxe表 <= 0 && counts.物流下单按钮 <= 0) return { counts };  // 非订单 frame，只回计数
124	
125	  // 渠道触发器 & 其外层链（判断该点哪一层才能弹开下拉）
126	  const chan = document.querySelector("input[placeholder*='渠道']");
127	  const chanInfo = chan ? {
128	    inputCls: chan.className,
129	    p1: chan.parentElement && chan.parentElement.className,
130	    p2: chan.parentElement && chan.parentElement.parentElement && chan.parentElement.parentElement.className,
131	    p3: chan.parentElement && chan.parentElement.parentElement && chan.parentElement.parentElement.parentElement && chan.parentElement.parentElement.parentElement.className,
132	  } : null;
133	  // 筛选模板触发器结构
134	  const tplInfo = tplEls.slice(0, 2).map((e) => ({ tag: e.tagName, cls: e.className, p1: e.parentElement && e.parentElement.className }));
135	  // main_label 样本：判断这些是"渠道下拉选项"还是"订单行里的渠道文字"
136	  const mlSample = [...document.querySelectorAll("span.main_label")].slice(0, 8)
137	    .map((e) => ({ text: (e.innerText || "").trim().slice(0, 28), visible: vis(e), p1: e.parentElement && e.parentElement.className }));
138	  // 当前【已打开】的下拉/弹层里的可见叶子文本（需先在页面手动点开下拉再探测）
139	  const containers = [...document.querySelectorAll(".el-popper,.el-select-dropdown,.el-dropdown-menu,.el-popover,.el-scrollbar,[class*=dropdown],[class*=popover]")].filter(vis);
140	  const openItems = [];
141	  containers.forEach((c) => {
142	    [...c.querySelectorAll("*")].forEach((e) => {
143	      if (e.children.length) return;
144	      const t = (e.innerText || "").trim();
145	      if (!t || t.length > 40 || !vis(e)) return;
146	      openItems.push({ cls: e.className, tag: e.tagName, text: t.slice(0, 28) });
147	    });
148	  });
149	
150	  return {
151	    counts,
152	    渠道触发器: chanInfo,
153	    筛选模板触发器: tplInfo,
154	    main_label样本: mlSample,
