160	// 主动探测：扩展自己去点渠道/模板的各层触发器，报告哪层能弹开下拉、选项真实类名。
161	function activeProbeInPage() {
162	  const vis = (el) => !!el && el.offsetParent !== null;
163	  const norm = (s) => (s || "").replace(/\s/g, "");
164	  function realClick(el) {
165	    if (!el) return;
166	    try { el.scrollIntoView({ block: "center" }); } catch (e) {}
167	    const r = el.getBoundingClientRect(), cx = r.left + r.width / 2, cy = r.top + r.height / 2;
168	    const base = { bubbles: true, cancelable: true, view: window, clientX: cx, clientY: cy, button: 0, buttons: 1 };
169	    for (const t of ["pointerover", "pointerdown", "mousedown", "pointerup", "mouseup", "click"]) {
170	      let ev;
171	      try { ev = t.startsWith("pointer") ? new PointerEvent(t, { ...base, pointerId: 1, isPrimary: true }) : new MouseEvent(t, base); }
172	      catch (e) { ev = new MouseEvent(t.replace("pointer", "mouse"), base); }
173	      el.dispatchEvent(ev);
174	    }
175	  }
176	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
177	  const input = document.querySelector("input[placeholder*='渠道']");
178	  const cont = input && input.closest(".select-container");
179	  const trig = input && input.closest(".popover_trigger");
180	
181	  return (async () => {
182	    const out = { 渠道trials: [] };
183	    async function tryChan(name, el) {
184	      if (!el) { out.渠道trials.push({ name, exists: false }); return; }
185	      realClick(el); await sleep(1200);
186	      const ml = [...document.querySelectorAll("span.main_label")].filter(vis);
187	      out.渠道trials.push({
188	        name, mainLabelVisible: ml.length,
189	        sample: ml.slice(0, 12).map((e) => (e.innerText || "").trim().slice(0, 28)),
190	        poppers: [...document.querySelectorAll("[class*=popper],.el-popover,.el-select-dropdown")].filter(vis).map((p) => p.className.slice(0, 42)).slice(0, 4),
191	      });
192	      try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
193	      await sleep(400); try { document.body.click(); } catch (e) {} await sleep(300);
194	    }
195	    await tryChan("input", input);
196	    await tryChan("select-container", cont);
197	    await tryChan("popover_trigger", trig);
198	
199	    // 筛选模板：点【文字恰为"筛选模板"的叶子元素】（与 content 脚本一致），避免点到消息铃铛
200	    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
201	    await sleep(400);
202	    const tplTrig = [...document.querySelectorAll("*")].find((e) => !e.children.length && norm(e.innerText) === "筛选模板");
203	    out.筛选模板_触发器父类 = tplTrig && tplTrig.parentElement && tplTrig.parentElement.className;
204	    realClick(tplTrig); await sleep(1200);
205	    out.筛选模板_poppers = [...document.querySelectorAll("[class*=popper],.el-popover")].filter(vis).map((p) => p.className.slice(0, 42)).slice(0, 5);
206	    out.筛选模板_选项 = [...document.querySelectorAll("[class*=popper] *,.el-popover *")]
207	      .filter((e) => !e.children.length && vis(e) && (e.innerText || "").trim())
208	      .slice(0, 25).map((e) => ({ cls: e.className.slice(0, 30), text: (e.innerText || "").trim().slice(0, 28) }));
209	    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
210	    return out;
211	  })();
212	}
