245	async function run(dry) {
246	  const R = self.HWC_RULES;
247	  log(`▶ 开始运行（${dry ? "DRY 空跑" : "真跑"}）`);
248	
249	  const erpTab = await findTab("https://www.sellfox.com/*");
250	  if (!erpTab) { log("✗ 没找到赛狐 ERP 标签页。请先在本浏览器打开并登录 ERP 订单页。"); return; }
251	  const wmsTab = await findTab("http://193.112.93.60:9999/*");
252	  if (!wmsTab) { log("✗ 没找到海外仓 WMS 标签页。请先在本浏览器打开并登录 WMS。"); return; }
253	
254	  // 读 WMS 当前登录店铺（顶部 Hi，XXX）——轮询到读出显示名为止
255	  log("· 读取 WMS 当前登录店铺…");
256	  const acct = await gotoUntil(wmsTab.id, INDEX_WMS, "wms",
257	    { op: "currentAccount" }, (r) => r && r.display);
258	  const display = acct && acct.display;
259	  const curLogin = R.shopByDisplay(display);
260	  if (!curLogin) {
261	    log(`✗ 读不到 WMS 当前登录店铺（顶部 Hi，${display || "?"}）。请确认 WMS 已登录后重试。`);
262	    return;
263	  }
264	  const curShop = R.SHOPS[curLogin].shop;
265	  log(`● 当前 WMS 登录店铺：${curShop}（${curLogin}）。本轮只处理该店铺对应的渠道。`);
266	
267	  const failures = [];
268	  const needSwitch = [];
269	
270	  for (const channel of R.CHANNEL_ORDER) {
271	    const login = R.channelAccountLogin(channel);
272	    if (login !== curLogin) { needSwitch.push(channel); continue; }
273	
274	    log("————————————————————————");
275	    log(`[渠道] ${channel}  ->  ${curShop}`);
276	
277	    // ① 重置 ERP 过滤：整页导航到订单页（等价 Python open_order_ship），轮询到 vxe 表就绪
278	    log("  · 打开 ERP 订单页并重置筛选…");
279	    const erpReady = await gotoUntil(erpTab.id, ERP_URL, "erp", { op: "ping" }, (r) => r && r.ok);
280	    if (!erpReady || !erpReady.ok) {
281	      log(`[渠道] ${channel} ERP 页面未就绪（可能会话失效/未登录/加载超时），跳过`);
282	      continue;
283	    }
284	    const er = await runOp(erpTab.id, "erp", { op: "placeOrder", channel, dry });
285	    if (!er) { log(`[渠道] ${channel} ERP 无响应（frame 未命中/未登录），跳过`); continue; }
286	    (er.logs || []).forEach(log);
287	    if (er.error) { log(`[渠道] ${channel} ERP 出错：${er.error}`); continue; }
288	    if (er.channelFilterFailed) { log(`[渠道] ${channel} 渠道筛选失败，跳过（防全量误下单）`); continue; }
289	    if (!er.count) { log(`[渠道] ${channel} 无待处理订单，跳过`); continue; }
290	    if (er.fail_orders && er.fail_orders.length)
291	      failures.push({ stage: "ERP物流下单", channel, orders: er.fail_orders });
292	
293	    let placed = er.success;
294	    if (placed == null) placed = dry ? er.count : 0;   // DRY 没真下单，用 count 代表“会下单数”
295	    if (!placed) { log(`[渠道] ${channel} 无成功下单，跳过 WMS 发货`); continue; }
296	
297	    // ② WMS 该店铺发货（本渠道末段对应的单一快递方；失败即留存不换）
298	    const courier = R.channelCourier(channel);
299	    log(`  · 打开 WMS 平台订单页（快递方 ${courier}）…`);
300	    const wmsReady = await gotoUntil(wmsTab.id, ORDERINFO_WMS, "wms", { op: "ping" }, (r) => r && r.ok);
301	    if (!wmsReady || !wmsReady.ok) {
302	      log(`[渠道] ${channel} WMS 平台订单页未就绪，跳过发货`);
303	      continue;
304	    }
305	    const wr = await runOp(wmsTab.id, "wms", { op: "processShop", courier, dry });
306	    if (!wr) { log(`[渠道] ${channel} WMS 无响应，跳过`); continue; }
307	    (wr.logs || []).forEach(log);
308	    if (wr.left_orders && wr.left_orders.length && !dry)
309	      failures.push({ stage: "WMS发货", channel, orders: wr.left_orders });
310	    log(`[渠道] ${channel} 闭环完成`);
311	  }
312	
313	  log("==============================");
314	  if (needSwitch.length) {
315	    const other = curLogin === "JMCAT" ? "金猫（JMSM）" : "黑猫（JMCAT）";
316	    log(`⏭ 另有 ${needSwitch.length} 个渠道属于【${other}】，本轮已跳过：`);
317	    needSwitch.forEach((c) => log("   · " + c));
318	    log(`👉 请把 WMS 切换登录到【${other}】后，再点一次「开始发货」。`);
319	  }
320	  if (failures.length) {
321	    log("⚠️ 失败/留存订单（需人工跟进）：");
322	    failures.forEach((f) => log(`   [${f.stage}] ${f.channel}: ${JSON.stringify(f.orders)}`));
323	  } else {
324	    log("✅ 本轮无失败/留存订单。");
325	  }
326	  log(dry ? "◼ DRY 空跑结束（未真实下单/发货）。" : "◼ 真跑结束。");
327	}
