329	// 与 popup 的长连接：弹窗一打开就连上，后台立刻把完整日志缓冲重放给它（故关了再开日志还在）。
330	chrome.runtime.onConnect.addListener((port) => {
331	  if (port.name !== "hwc") return;
332	  ports.add(port);
333	  port.onDisconnect.addListener(() => ports.delete(port));
334	  loadBufferIfEmpty().then(() => {
335	    try { port.postMessage({ type: "buffer", lines: logBuffer, running }); } catch (e) {}
336	  });
337	  port.onMessage.addListener(async (msg) => {
338	    if (!msg) return;
339	    if (msg.cmd === "probe") {
340	      logBuffer = [];
341	      broadcast({ type: "status", running: false });
342	      try { await probeErp(); }
343	      catch (e) { log("✗ 探测异常：" + String((e && e.stack) || e)); }
344	      finally { broadcast({ type: "done" }); }
345	      return;
346	    }
347	    if (msg.cmd === "run") {
348	      if (running) { log("（已有任务在运行中，忽略重复开始）"); return; }
349	      running = true;
350	      logBuffer = [];
351	      startKeepAlive();
352	      broadcast({ type: "status", running: true });
353	      try { await run(!!msg.dry); }
354	      catch (e) { log("✗ 运行异常：" + String((e && e.stack) || e)); }
355	      finally {
356	        running = false;
357	        stopKeepAlive();
358	        try { chrome.storage.session.set({ hwcLog: logBuffer, hwcRunning: false }); } catch (e) {}
359	        broadcast({ type: "status", running: false });
360	        broadcast({ type: "done" });
361	      }
362	    }
