const cn = (el) => (el && typeof el.className === "string" ? el.className : (el && el.className && el.className.baseVal) || "");
const leafText = (e) => (e.innerText || "").trim();
// 只发 mousedown/mouseup（不发 click）——有些自定义 popover 靠 mousedown 展开、click 反而触发 outside-close。
const mousedownOnly = (el) => {
  const r = el.getBoundingClientRect();
  const base = { bubbles: true, cancelable: true, view: window, clientX: r.left + r.width / 2, clientY: r.top + r.height / 2, button: 0, buttons: 1 };
  for (const t of ["pointerdown", "mousedown", "pointerup", "mouseup"]) {
    let ev; try { ev = t.startsWith("pointer") ? new PointerEvent(t, { ...base, pointerId: 1, isPrimary: true }) : new MouseEvent(t, base); } catch (e) { ev = new MouseEvent(t.replace("pointer", "mouse"), base); }
    el.dispatchEvent(ev);
  }
};
const focusThenClick = (el) => { try { el.focus(); } catch (e) {} realClick(el); };
return (async () => {
  const out = { 渠道trials: [] };
  // trigger=不同点法；点后 diff 出【新增的全部可见元素】，不再只盯 main_label，好看清渠道下拉真身。
  async function tryChan(name, el, trigger) {
    if (!el) { out.渠道trials.push({ name, exists: false }); return; }
    const before = new Set([...document.querySelectorAll("body *")].filter(vis));
    try { trigger(el); } catch (e) {}
    await sleep(1500);
    const appeared = [...document.querySelectorAll("body *")].filter((e) => vis(e) && !before.has(e));
    const leaves = appeared.filter((e) => !e.children.length && leafText(e));
    const ml = [...document.querySelectorAll("span.main_label")].filter(vis);
    out.渠道trials.push({
      name,
      新增可见元素数: appeared.length,
      新增class: [...new Set(appeared.map((e) => cn(e).split(" ")[0]).filter(Boolean))].slice(0, 14),
      新增叶子文本: [...new Set(leaves.map(leafText))].slice(0, 20).map((t) => t.slice(0, 24)),
      mainLabelVisible: ml.length,
      mainLabel样本: ml.slice(0, 10).map((e) => leafText(e).slice(0, 24)),
    });
    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
    await sleep(400); try { document.body.click(); } catch (e) {} await sleep(300);
  }
  await tryChan("input:realClick", input, realClick);
  await tryChan("popover_trigger:realClick", trig, realClick);
  await tryChan("input:focus+click", input, focusThenClick);
  await tryChan("input:mousedownOnly", input, mousedownOnly);

