// 渠道选项异步加载(下拉用虚拟滚动 vue-recycle-scroller) + 合成点击偶发不生效（实测两次探测
// 同样 realClick 一次弹开 5 项、一次 0 项）。故轮询等 span.main_label 出现、最多重试 3 轮点击，
// 别固定 sleep 后就读（读到空=误判无此渠道=跳过）。
const readLabels = () => H.qsa("span.main_label").filter((e) => H.isVisible(e));
let labels = [];
for (let attempt = 0; attempt < 3 && !labels.length; attempt++) {
  H.realClick(trigger);
  const got = await H.waitFor(() => { const l = readLabels(); return l.length ? l : null; }, { timeout: 4000, interval: 300 });
  labels = got || [];
  if (!labels.length) { L.push(`[ERP] 渠道下拉未弹开(第${attempt + 1}次)，重试…`); await H.sleep(600); }
}
if (!labels.length) { L.push("[ERP] 渠道下拉多次未弹开，跳过本渠道"); return { ok: false, available: [] }; }
// span.main_label 精确匹配（别用包含——订单行物流信息列也含渠道文字会误点）
const picked = labels.find((el) => (el.innerText || "").trim() === channel);
if (!picked) {
  const available = [...new Set(labels.map((e) => (e.innerText || "").trim()).filter(Boolean))].sort();
  L.push(`[ERP] 未找到渠道选项：${channel}；当前下拉可选渠道=${JSON.stringify(available)}`);
  try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
  return { ok: false, available };
}

