// 渠道筛选。触发 input[placeholder*='渠道'] -> 弹层 span.main_label 精确匹配 -> 确定。
// 返回 {ok, available}。available = 找不到时下拉里实际可选渠道（便于判断是漏筛还是本就没单）。
async function filterByChannel(channel, L) {
  if (!channel) return { ok: true };
  dismissNotifications();
  // 先按 Esc 清掉可能残留的弹层（如上一步筛选模板未关的 popover）。渠道弹层是 single_el_popover
  // 单例机制：若有旧弹层开着，点渠道 input 只会关旧弹层、不弹渠道下拉 → 选项为空（实测）。
  try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
  await H.sleep(400);
  // 点渠道 input 前先等页面稳定（模板 popover/loading 遮罩残留会让下拉弹不开）。
  await waitPageSettle();
  const trigger = document.querySelector("input[placeholder*='渠道']");
  if (!trigger) { L.push("[ERP] 未找到渠道筛选输入框"); return { ok: false, available: [] }; }
  // 渠道选项异步加载(下拉用虚拟滚动 vue-recycle-scroller) + 合成点击偶发不生效（实测两次探测
  // 同样 realClick 一次弹开 5 项、一次 0 项）。故轮询等 span.main_label 出现、最多重试 3 轮点击，
  // 别固定 sleep 后就读（读到空=误判无此渠道=跳过）。
  const readLabels = () => H.qsa("span.main_label").filter((e) => H.isVisible(e));
  let labels = [];
  for (let attempt = 0; attempt < 3 && !labels.length; attempt++) {
    H.realClick(trigger);
    const got = await H.waitFor(() => { const l = readLabels(); return l.length ? l : null; }, { timeout: 4000, interval: 300 });
    labels = got || [];
    if (!labels.length) { L.push(`[ERP] 渠道下拉未弹开(第${attempt + 1}次)，重试…`); await waitPageSettle(3000); await H.sleep(400); }

