input.new_string:
if (!document.querySelector("input[placeholder*='渠道']")) { L.push("[ERP] 未找到渠道筛选输入框"); return { ok: false, available: [] }; }
// 渠道选项异步加载(虚拟滚动 vue-recycle-scroller) + 合成点击偶发不生效；且实测「模板一应用→渠道
// 三次全不弹开且 blockers=[]」→ 疑模板刷新使工具栏重渲染、旧 input 引用失效。故【每轮重新抓 input】
// + focus+click(探测证实 focus+click 也能弹开)，未弹开时打细诊断(connected/disabled/下拉容器数)。
const readLabels = () => H.qsa("span.main_label").filter((e) => H.isVisible(e));
let labels = [];
let lastDiag = "";
for (let attempt = 0; attempt < 3 && !labels.length; attempt++) {
  const trig = document.querySelector("input[placeholder*='渠道']");   // 每轮重抓，防重渲染后引用失效
  if (!trig) { lastDiag = "渠道input不存在"; await H.sleep(600); continue; }
  try { trig.focus(); } catch (e) {}
  H.realClick(trig);
  const got = await H.waitFor(() => { const l = readLabels(); return l.length ? l : null; }, { timeout: 4000, interval: 300 });
  labels = got || [];
  if (!labels.length) {
    const popvis = H.qsa(".el-popover, .select-menu").filter((e) => H.isVisible(e)).length;
    lastDiag = `connected=${trig.isConnected} disabled=${trig.disabled} readonly=${trig.readOnly} 可见下拉容器=${popvis}`;
    L.push(`[ERP] 渠道下拉未弹开(第${attempt + 1}次)，重试…（${lastDiag}）`);
    await waitPageSettle(3000); await H.sleep(400);
  }
}
if (!labels.length) {
  L.push(`[ERP] 渠道下拉多次未弹开，跳过本渠道（${lastDiag}；可见弹层/遮罩=${JSON.stringify(visibleBlockers())}）`);
  return { ok: false, available: [] };
}

