107	    // 渠道选项异步加载(虚拟滚动 vue-recycle-scroller) + 合成点击偶发不生效；且实测「模板一应用→渠道
108	    // 三次全不弹开且 blockers=[]」→ 疑模板刷新使工具栏重渲染、旧 input 引用失效。故【每轮重新抓 input】
109	    // + focus+click(探测证实 focus+click 也能弹开)，未弹开时打细诊断(connected/disabled/下拉容器数)。
110	    const readLabels = () => H.qsa("span.main_label").filter((e) => H.isVisible(e));
111	    let labels = [];
112	    let lastDiag = "";
113	    for (let attempt = 0; attempt < 3 && !labels.length; attempt++) {
114	      const trig = document.querySelector("input[placeholder*='渠道']");   // 每轮重抓，防重渲染后引用失效
115	      if (!trig) { lastDiag = "渠道input不存在"; await H.sleep(600); continue; }
116	      try { trig.focus(); } catch (e) {}
117	      H.realClick(trig);
118	      const got = await H.waitFor(() => { const l = readLabels(); return l.length ? l : null; }, { timeout: 4000, interval: 300 });
119	      labels = got || [];
120	      if (!labels.length) {
121	        const popvis = H.qsa(".el-popover, .select-menu").filter((e) => H.isVisible(e)).length;
122	        lastDiag = `connected=${trig.isConnected} disabled=${trig.disabled} readonly=${trig.readOnly} 可见下拉容器=${popvis}`;
123	        L.push(`[ERP] 渠道下拉未弹开(第${attempt + 1}次)，重试…（${lastDiag}）`);
124	        await waitPageSettle(3000); await H.sleep(400);
125	      }
126	    }
127	    if (!labels.length) {
128	      L.push(`[ERP] 渠道下拉多次未弹开，跳过本渠道（${lastDiag}；可见弹层/遮罩=${JSON.stringify(visibleBlockers())}）`);
129	      return { ok: false, available: [] };
130	    }
131	    // span.main_label 精确匹配（别用包含——订单行物流信息列也含渠道文字会误点）
132	    const picked = labels.find((el) => (el.innerText || "").trim() === channel);
133	    if (!picked) {
134	      const available = [...new Set(labels.map((e) => (e.innerText || "").trim()).filter(Boolean))].sort();
135	      L.push(`[ERP] 未找到渠道选项：${channel}；当前下拉可选渠道=${JSON.stringify(available)}`);
136	      try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
