input.new_string:
// 关键实测(2026-07-15)：模板应用后点渠道，弹层【确实开了】(el-popover+select-menu 可见)，但里面
// span.main_label【空】=选项没加载出来。故区分「弹层开」与「选项到位」：弹层一开就耐心等选项(8s，
// 不急着换点法/不 Escape 打断加载)；等够还空就 dump 弹层内部结构，定性是"加载中/暂无/虚拟滚动没渲染"。
const readLabels = () => H.qsa("span.main_label").filter((e) => H.isVisible(e));
const ddOpen = () => H.qsa(".el-popover, .select-menu").some((e) => H.isVisible(e));
const chan = () => document.querySelector("input[placeholder*='渠道']");
const openers = [
  { name: "realClick", fn: () => H.realClick(chan()) },
  { name: "双击", fn: async () => { H.realClick(chan()); await H.sleep(300); H.realClick(chan()); } },
  { name: "focus+click", fn: () => { const i = chan(); try { i.focus(); } catch (e) {} H.realClick(i); } },
  { name: "popover_trigger", fn: () => { const t = chan() && chan().closest(".popover_trigger"); if (t) H.realClick(t); } },
  { name: "select-container", fn: () => { const t = chan() && chan().closest(".select-container"); if (t) H.realClick(t); } },
];
let labels = [];
let usedOpener = "";
for (const op of openers) {
  if (!chan()) break;
  try { await op.fn(); } catch (e) {}
  const opened = await H.waitFor(() => (ddOpen() || readLabels().length) ? true : null, { timeout: 2500, interval: 200 });
  if (!opened) {
    L.push(`[ERP] 渠道点法「${op.name}」弹层未开，换下一种…`);
    try { document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); } catch (e) {}
    await H.sleep(400);
    continue;
  }
  // 弹层开了，耐心等选项加载（虚拟滚动/异步）
  const got = await H.waitFor(() => { const l = readLabels(); return l.length ? l : null; }, { timeout: 8000, interval: 400 });
  if (got && got.length) { labels = got; usedOpener = op.name; break; }
  // 弹层开着但选项一直空 → dump 内部结构诊断（换点法无意义，是数据/加载问题）
  const dd = H.qsa(".el-popover, .select-menu").find((e) => H.isVisible(e));
  const info = dd ? {
    文本: (dd.innerText || "").replace(/\s+/g, " ").trim().slice(0, 140),
    有搜索框: !!dd.querySelector("input"),
    有虚拟滚动: !!dd.querySelector(".vue-recycle-scroller"),
    子class: [...new Set([...dd.querySelectorAll("*")].slice(0, 200)
      .map((e) => (typeof e.className === "string" ? e.className : "").split(" ")[0]).filter(Boolean))].slice(0, 12),
  } : "弹层已消失";
  L.push(`[ERP] 渠道点法「${op.name}」弹层开但选项空，弹层内部=${JSON.stringify(info)}`);
  break;   // 弹层能开、问题在选项数据，换点法没用，停止
}
if (!labels.length) {
  L.push(`[ERP] 渠道下拉未取到选项，跳过本渠道（可见弹层/遮罩=${JSON.stringify(visibleBlockers())}）`);
  return { ok: false, available: [] };
}
L.push(`[ERP] 渠道下拉已弹开（点法=${usedOpener}，${labels.length}项）`);

